<template><view :data-skin="scenicSkin" class="visual-page safe"><SceneBackdrop :src="backgrounds.engagement" :shade=".65" fractured/><TopBar title="人物档案" eyebrow="THE PEOPLE IN YOUR LIFE" @back="back" @settings="settings"/><view class="character-layout visual-content"><view class="character-list"><button role="button" tabindex="0" @keydown.enter.prevent="activateFocused" @keydown.space.prevent="activateFocused" v-for="c in characters" :key="c.id" :aria-label="c.name" @click="selected=c.id"><AssetImage class="list-skin" :src="c.id===selected?uiAssets.character.active:uiAssets.character.idle" fit="fill"/><CharacterPortraitFrame class="list-avatar" :src="c.portrait" :selected="c.id===selected"/><text>{{c.name}}</text></button></view><view class="portrait-stage"><AssetImage class="portrait-art" :src="heroPortrait" position="center top" fit="contain"/><view class="portrait-caption"><text class="visual-title">{{character.name}}</text><text class="visual-copy">{{character.summary}}</text><text v-if="gameStore.state.developerMode" class="quality">{{character.quality}}</text></view></view><AssetPanel class="profile" variant="sidebar"><CharacterPortraitFrame class="profile-avatar" :src="character.portrait" selected/><view class="profile-tabs"><button role="button" tabindex="0" @keydown.enter.prevent="activateFocused" @keydown.space.prevent="activateFocused" v-for="t in tabs" :key="t" :class="{active:tab===t}" @click="tab=t">{{t}}</button></view><text v-if="tab!=='基本信息'" class="profile-tab-copy">{{tab==='关系事件'?relationCopy:hiddenCopy}}</text><view v-show="tab==='基本信息'"><text class="section-label">当前认知</text><text class="profile-title">{{character.title}}</text><view class="relation-list"><view v-for="status in statuses" :key="status.label"><AssetImage :src="status.icon" fit="contain"/><text>{{status.label}}</text><text class="muted">{{gameStore.state.developerMode?(gameStore.state.stats[status.key]??0):'待观察'}}</text></view></view><AssetImage class="visual-divider" :src="uiAssets.decorations.spark" fit="contain"/><text class="visual-copy">有些真相，只有靠近，才看得见。</text></view></AssetPanel></view></view></template>
<script setup lang="ts">
import {activateFocused} from '../../utils/keyboard';

import {goBack} from '../../utils/navigation'
import {computed,ref} from 'vue';import CharacterPortraitFrame from '../../components/character/CharacterPortraitFrame.vue';import {gameStore} from '../../store/game';import TopBar from '../../components/TopBar.vue';import AssetImage from '../../components/common/AssetImage.vue';import AssetPanel from '../../components/common/AssetPanel.vue';import SceneBackdrop from '../../components/common/SceneBackdrop.vue';import {characters} from '../../data/characters';import {backgrounds} from '../../data/backgrounds';import {uiAssets} from '../../config/ui-assets';const selected=ref('shenzhiyi'),character=computed(()=>characters.find(c=>c.id===selected.value)!);const statuses=[{label:'信任',key:'trust',icon:uiAssets.status.trust},{label:'警惕',key:'alert',icon:uiAssets.status.alert},{label:'控制',key:'control',icon:uiAssets.status.control},{label:'裂痕',key:'fracture',icon:uiAssets.status.fracture},{label:'依赖',key:'dependence',icon:uiAssets.status.dependence}];function back(){goBack()}function settings(){uni.navigateTo({url:'/pages/settings/index'})}const heroPortrait=computed(()=>('hero' in character.value&&character.value.hero)||character.value.portrait);const tabs=['基本信息','关系事件','隐藏内容'],tab=ref('基本信息');const relationCopy=computed(()=>gameStore.state.choiceHistory.filter(h=>h.text?.includes(character.value.name.slice(0,1))).map(h=>h.text).join(' · ')||'那些交汇的瞬间，还需要在故事中慢慢看清。');const hiddenCopy=computed(()=>gameStore.state.playthrough>1?'记忆已被保留，新的认识仍需亲自抵达。':'有些故事，要走近之后才会知道。');</script>
